sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
console.log('entered');
 var dataResource = api.data.look_up_multiple_records_1;
 console.log(dataResource);
 console.log('Length :'+dataResource.length);
 var drop = dataResource.results.map(record =>({
   id : record.code.value,
   label:record.code.displayValue
 }));
 api.setState('dropValue',drop);
 console.log('WBS CS 1'+api.state.wbsNumber);

 var currentMonth = new Date().getMonth();
    var allMonths = {
        0: 'january',
        1: 'february',
        2: 'march',
        3: 'april',
        4: 'may',
        5: 'june',
        6: 'july',
        7: 'august',
        8: 'september',
        9: 'october',
        10: 'november',
        11: 'december'
    };
    console.log('Current Month '+currentMonth);
    for (var month in allMonths) {
        if (parseInt(month) < currentMonth) {
          api.setState(allMonths[month], true);

        }
    }

}
